package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
class CoinExchangeStoreTest {
 @TempDir Path directory;UUID player=UUID.randomUUID();
 EconomyStore enrolled()throws Exception{var s=EconomyStore.open(directory);s.changeProfession(UUID.randomUUID(),player,"enroll","","merchant");return s;}
 @Test void adjacentRatesConserveExactFaceValueAndRejectInvalidTerms(){var values=Map.of("copper",1,"silver",10,"gold",100,"platinum",1000);for(var from:values.keySet())for(var to:values.keySet()){if(Math.max(values.get(from),values.get(to))==10*Math.min(values.get(from),values.get(to))){var t=new CoinExchangeTerms(from,to,230);assertEquals(t.inputs()*values.get(from),t.outputs()*values.get(to));assertEquals(t,CoinExchangeTerms.parse(t.action(),230));}else assertThrows(IllegalArgumentException.class,()->new CoinExchangeTerms(from,to,1));}for(int count:new int[]{0,-1,231,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->new CoinExchangeTerms("copper","silver",count));}
 @Test void onlyNativePostReceiptCommitsKindsAndDuplicateRecoveryCannotMint()throws Exception{var s=enrolled();var first=s.prepareCoinExchange(UUID.randomUUID(),player,new CoinExchangeTerms("copper","silver",1));assertTrue(s.merchantProof(player).exchanges().isEmpty());assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),first.previousReceipt())));assertTrue(s.merchantProof(player).exchanges().isEmpty());for(var pair:List.of("exchange:copper:silver","exchange:silver:gold")){var p=s.prepareCoinExchange(UUID.randomUUID(),player,CoinExchangeTerms.parse(pair,1));assertTrue(s.recoverItem(new EconomyStore.Receipt(s.id(),p.sequence())));assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),p.sequence())));}assertTrue(s.merchantProof(player).ready(MerchantTransactionQuests.EXCHANGE));var award=UUID.randomUUID();s.completeMerchantTransactionQuest(award,player,MerchantTransactionQuests.EXCHANGE);s.completeMerchantTransactionQuest(award,player,MerchantTransactionQuests.EXCHANGE);var reopened=EconomyStore.open(directory);assertEquals(0,reopened.balance(player));assertEquals(100,reopened.professions(player).track(Profession.MERCHANT).xp());assertEquals(s.merchantProof(player),reopened.merchantProof(player));assertEquals(s.expectedReceipt(player),reopened.expectedReceipt(player));}
 @Test void crashAfterPrepareAndAfterCommitRequiresMatchingNativeReceipt()throws Exception{var s=enrolled();var failed=EconomyStore.open(directory,(path,tag)->{AtomicNbt.write(path,tag);throw new IOException("After prepare rename");});assertThrows(IOException.class,()->failed.prepareCoinExchange(UUID.randomUUID(),player,new CoinExchangeTerms("copper","silver",1)));s=EconomyStore.open(directory);var pending=s.pendingItem().orElseThrow();assertTrue(s.merchantProof(player).exchanges().isEmpty());var interrupted=EconomyStore.open(directory,(path,tag)->{AtomicNbt.write(path,tag);throw new IOException("After exchange commit rename");});assertThrows(IOException.class,()->interrupted.recoverItem(new EconomyStore.Receipt(interrupted.id(),pending.sequence())));var reopened=EconomyStore.open(directory);assertEquals(Set.of("copper:silver"),reopened.merchantProof(player).exchanges());assertFalse(reopened.recoverItem(new EconomyStore.Receipt(reopened.id(),pending.sequence())));assertEquals(0,reopened.balance(player));assertEquals(0,reopened.professions(player).track(Profession.MERCHANT).xp());}
 @Test void wrongNativeStoreCannotCommitAndInverseExchangeIsNotApprovedUpConversion()throws Exception{var s=enrolled();var p=s.prepareCoinExchange(UUID.randomUUID(),player,new CoinExchangeTerms("silver","copper",1));assertThrows(IOException.class,()->s.recoverItem(new EconomyStore.Receipt(UUID.randomUUID(),p.sequence())));assertTrue(s.merchantProof(player).exchanges().isEmpty());s.recoverItem(new EconomyStore.Receipt(s.id(),p.sequence()));assertFalse(s.merchantProof(player).ready(MerchantTransactionQuests.EXCHANGE));assertThrows(IllegalStateException.class,()->s.completeMerchantTransactionQuest(UUID.randomUUID(),player,MerchantTransactionQuests.EXCHANGE));}
}
